preConditionHook:
// MA DISTANCE REGIME (Brian's notes ON-68, #68): mean of (close - EMA)
// over longWindow >= minLongAtr ATRs and |mean over shortWindow| <=
// maxShortAtr ATRs (long); short mirrors the long-window term.
// MultiWalk's WFSafe_Xaverage, ported unchanged from EmaGapBar (the EMA
// reference, with the measurements): price seed on the first calculated bar
// (ctx.CurrentBar() == 1), recurrence x + sf*(p - x) in ONE statement,
// sf = 2/(Length+1) from the raw input every bar, state carried on a length
// change (EL_XAverage_Lag_Probe.txt, 2026-09-17).
emaSf = 2.0 / (emaLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaVal = close[0];
} else {
    emaVal = emaVal + emaSf * (close[0] - emaVal);
}
dist = close[0] - emaVal;
// EL: Average(dist, N) over a VARIABLE reads its zero-filled history and
// recomputes fresh every bar, summing NEWEST-FIRST ([0] .. [N-1]). Mirrored in
// a zero-initialized ring buffer deep enough for both windows, read from the
// newest slot backwards; re-seeded if the depth changes.
distDepth = (int)longWindow;
if ((int)shortWindow > distDepth) {
    distDepth = (int)shortWindow;
}
if (distDepth < 1) {
    distDepth = 1;
}
if (distHistory.size() != (std::size_t)distDepth) {
    distHistory.assign((std::size_t)distDepth, 0.0);
    distCursor = 0;
}
distHistory[distCursor] = dist;
dLong = 0.0;
for (int i = 0; i < (int)longWindow; ++i) {
    dLong += distHistory[(distCursor + distHistory.size() - (std::size_t)i) % distHistory.size()];
}
dLong /= (int)longWindow;
dShort = 0.0;
for (int i = 0; i < (int)shortWindow; ++i) {
    dShort += distHistory[(distCursor + distHistory.size() - (std::size_t)i) % distHistory.size()];
}
dShort /= (int)shortWindow;
distCursor = (distCursor + 1) % distHistory.size();
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
distReady = ctx.CurrentBar() > (int)longWindow - 1;
